// Safety note: the SVG returned below is generated by node-qrcode from our own base64url
// token URL. It contains no user input, so rendering it with dangerouslySetInnerHTML is safe.
import QRCode from "qrcode";

/** Public URL of a pass. This is all the QR contains: no names, emails or phone numbers. */
export function passUrl(token: string) {
  const base = process.env.APP_BASE_URL ?? "http://localhost:3000";
  return new URL(`/p/${token}`, base).toString();
}

/** SVG markup for a pass QR code. High error correction copes with cracked screens. */
export async function passQrSvg(token: string) {
  return QRCode.toString(passUrl(token), { type: "svg", errorCorrectionLevel: "Q", margin: 2, color: { dark: "#000000", light: "#ffffff" } });
}
